{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "ML218 in rhesus monkeys achieved CSF concentrations with a Tmax similar to plasma, directly demonstrating CNS distribution after systemic dosing; the high transfer score and shared basic-amine/heterocycle features support meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Blonanserin showed a human brain/plasma concentration ratio of 3.38 by PET, indicating good BBB penetration; this direct human evidence with a halogenated aromatic and basic N-methylamine motif is highly transferable to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine reached brain concentrations almost equal to plasma in rats, directly showing BBB penetration for a rigid N-methylated polycyclic amine; the high transfer score supports the query's CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Hernandezine after IV dosing in rats reached a brain Cmax of 372 ng/ml versus plasma Cmax of 433.6 ng/ml, demonstrating substantial brain exposure for a complex basic polycyclic alkaloid; this supports the query's ability to access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "[18F]NCQ 258 crossed the BBB rapidly in cynomolgus monkeys in a PET study, providing direct in vivo evidence that a halogenated aromatic basic amine can achieve meaningful CNS entry; this is transferable to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Semagacestat CSF measurements in humans indicated good CNS penetration, providing direct human CSF evidence that a moderately lipophilic, transporter-sensitive molecule can still achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Dihydromorphine whole-body autoradiography showed essentially no CNS accumulation, but this record has a very low transfer score (0.0528) and lacks the lipophilic halogenated aromatic and rigid amine features of the query, so it is a weak contradictory anchor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer direct CNS measurements—CSF profiles, PET brain/plasma ratios, and brain tissue distribution in monkeys, humans, and rats—consistently show meaningful BBB penetration for structurally related rigid basic amines with aromatic halogens and low TPSA. The single negative record is low-transfer and outweighed by the convergent positive evidence.",
  "evidence_gaps": [
    "No direct in vivo brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux transporter involvement for the query is not directly measured, though high lipophilicity and basic amine suggest possible P-gp liability.",
    "Human CNS exposure data for the exact query are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

